        // ── Perfmon overlay for the Events page ─────────────────────────────
        private void InitPerfmonEventsOverlay()
        {
            if (_perfmonEventsSubscribed) return;

            if (PerfmonCpuCanvas   != null) _perfCpuSpark   = new PerfmonSparkline(PerfmonCpuCanvas,   "CPU",   "%",    WpfColor.FromRgb(59, 130, 246), 100f);
            if (PerfmonQueueCanvas != null) _perfQueueSpark = new PerfmonSparkline(PerfmonQueueCanvas, "Queue", "thr",  WpfColor.FromRgb(245, 158, 11)) { ThresholdValue = 5f };
            if (PerfmonPagesCanvas != null) _perfPagesSpark = new PerfmonSparkline(PerfmonPagesCanvas, "Pages", "/s",   WpfColor.FromRgb(168, 85, 247))  { ThresholdValue = 1000f };
            if (PerfmonNetCanvas   != null) _perfNetSpark   = new PerfmonSparkline(PerfmonNetCanvas,   "Net",   "KB/s", WpfColor.FromRgb(34, 197, 94));

            // Dashboard mini sparklines — init lazy (canvas may not exist at startup)
            if (FindName("PerfmonQueueCanvas") == null) // queue is on dashboard now — different x:Name needed
            { /* already handled above */ }
            // Init dashboard Queue/Pages sparklines (small 28px height)
            _ = Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, new Action(() =>
            {
                try
                {
                    // PerfmonQueueCanvas and PerfmonPagesCanvas are now on the Dashboard
                    if (_perfQueueSpark == null && PerfmonQueueCanvas != null)
                        _perfQueueSpark = new PerfmonSparkline(PerfmonQueueCanvas, "", "thr", WpfColor.FromRgb(245, 158, 11)) { ThresholdValue = 5f };
                    if (_perfPagesSpark == null && PerfmonPagesCanvas != null)
                        _perfPagesSpark = new PerfmonSparkline(PerfmonPagesCanvas, "", "/s", WpfColor.FromRgb(168, 85, 247)) { ThresholdValue = 1000f };
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }));

            SMDWin.Services.PerfmonService.Instance.DataUpdated += OnPerfmonTick;
            _perfmonEventsSubscribed = true;
        }

        private void OnPerfmonTick()
        {
            if (!Dispatcher.CheckAccess()) { _ = Dispatcher.InvokeAsync(OnPerfmonTick); return; }

            var pm = SMDWin.Services.PerfmonService.Instance;

            _perfCpuSpark?.Draw(pm.GetHistory(SMDWin.Services.PerfmonService.CpuTotal));
            _perfQueueSpark?.Draw(pm.GetHistory(SMDWin.Services.PerfmonService.CpuQueueLength));
            _perfPagesSpark?.Draw(pm.GetHistory(SMDWin.Services.PerfmonService.MemPagesSec));

            var netHist = pm.GetHistory(SMDWin.Services.PerfmonService.NetBytesTotalSec);
            for (int i = 0; i < netHist.Length; i++) netHist[i] /= 1024f;
            _perfNetSpark?.Draw(netHist);

            if (PerfmonCpuLabel   != null) PerfmonCpuLabel.Text  = $"{pm.CpuPercent:F0}%";
            if (PerfmonQueueLabel != null) PerfmonQueueLabel.Text = $"{pm.QueueLength:F0} thr";
            if (PerfmonPagesLabel != null) PerfmonPagesLabel.Text = $"{pm.PagesSec:F0}/s";
            if (PerfmonNetLabel   != null) PerfmonNetLabel.Text   = $"{pm.LastValue(SMDWin.Services.PerfmonService.NetBytesTotalSec) / 1024f:F1} KB/s";

            // Network overview sparklines
            if (_currentPanel == "Network")
            {
                try
                {
                    if (_netOverviewDownSpark == null && NetOverviewDownCanvas != null
                        && NetOverviewDownCanvas.ActualWidth >= 10)
                    {
                        _netOverviewDownSpark = new PerfmonSparkline(NetOverviewDownCanvas, "", "KB/s",
                            System.Windows.Media.Color.FromRgb(34, 197, 94), showLabels: false);
                        AppLogger.Info($"Network sparkline (Down) created — buffer already has {_netOverviewDown.Count} values, canvas width={NetOverviewDownCanvas.ActualWidth:F0}");
                    }

                    if (_netOverviewUpSpark == null && NetOverviewUpCanvas != null
                        && NetOverviewUpCanvas.ActualWidth >= 10)
                        _netOverviewUpSpark = new PerfmonSparkline(NetOverviewUpCanvas, "", "KB/s",
                            System.Windows.Media.Color.FromRgb(96, 165, 250), showLabels: false);

                    var downArr = _netOverviewDown.Count >= 2
                        ? _netOverviewDown.ToArray()
                        : Array.ConvertAll(_cNetDown ?? _arrNetDown, v => float.IsNaN(v) ? 0f : v);
                    var upArr   = _netOverviewUp.Count >= 2
                        ? _netOverviewUp.ToArray()
                        : Array.ConvertAll(_cNetUp ?? _arrNetUp,   v => float.IsNaN(v) ? 0f : v);
                    // Scale: a 1 MB/s minimum threshold (small 20–30 KB/s peaks do not fill the chart); above it autoscale by the maximum
                    // in the visible window, rounded to a "nice" step (1/2/5 × 10^n).
                    float rawMaxDown = NiceNetScale(downArr.Length > 0 ? downArr.Max() : 0f);
                    float rawMaxUp   = NiceNetScale(upArr.Length   > 0 ? upArr.Max()   : 0f);

                    float finalMaxDown = _netOverviewMaxCacheDown.HasValue
                        ? (rawMaxDown > _netOverviewMaxCacheDown.Value ? rawMaxDown : _netOverviewMaxCacheDown.Value * 0.98f)
                        : rawMaxDown;
                    if (finalMaxDown < rawMaxDown) finalMaxDown = rawMaxDown;
                    _netOverviewMaxCacheDown = finalMaxDown;
                    float finalMaxUp = _netOverviewMaxCacheUp.HasValue
                        ? (rawMaxUp > _netOverviewMaxCacheUp.Value ? rawMaxUp : _netOverviewMaxCacheUp.Value * 0.98f)
                        : rawMaxUp;
                    if (finalMaxUp < rawMaxUp) finalMaxUp = rawMaxUp;
                    _netOverviewMaxCacheUp = finalMaxUp;

                    if (downArr.Length > 0) _netOverviewDownSpark?.Draw(downArr, finalMaxDown);
                    if (upArr.Length > 0)   _netOverviewUpSpark?.Draw(upArr, finalMaxUp);

                    if (TxtNetOverviewDownLabel != null) TxtNetOverviewDownLabel.Text = FormatKBps(finalMaxDown);
                    if (TxtNetOverviewUpLabel   != null) TxtNetOverviewUpLabel.Text   = FormatKBps(finalMaxUp);

                    // Download / Upload on the Network page are written by RenderNetTraffic, from the same data as the chart
                }
                catch (Exception ex) { AppLogger.Debug(ex.Message); }
            }
        }
    }
}
